args.CommandLine:
$targets = @(
    "$env:LOCALAPPDATA\Temp",
    "$env:LOCALAPPDATA\pip\cache",
    "$env:LOCALAPPDATA\npm-cache",
    "$env:USERPROFILE\.cache",
    "$env:USERPROFILE\.gemini",
    "$env:USERPROFILE\Downloads",
    "C:\Windows\Temp",
    "C:\Windows\SoftwareDistribution\Download"
)

foreach ($path in $targets) {
    if (Test-Path $path) {
        $size = (Get-ChildItem -Path $path -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        $sizeMB = [math]::Round($size / 1MB, 2)
        $sizeGB = [math]::Round($size / 1GB, 2)
        [PSCustomObject]@{
            Path = $path
            SizeMB = $sizeMB
            SizeGB = $sizeGB
        }
    }
}

$results = @()
$cDirs = Get-ChildItem -Path "C:\" -Directory -Force -ErrorAction SilentlyContinue
foreach ($d in $cDirs) {
    if ($d.Name -in @('$Recycle.Bin', 'System Volume Information')) {
        continue
    }
    try {
        $size = (Get-ChildItem -Path $d.FullName -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        $results += [PSCustomObject]@{
            Folder = $d.FullName
            SizeGB = [math]::Round($size / 1GB, 2)
        }
    } catch {}
}
$results | Sort-Object SizeGB -Descending | Format-Table -AutoSize

